raw_evidence.reproduction_tcl:
open_checkpoint {C:/Users/wyh/Desktop/chipcourse/chip_design_demo_raw0b/tools/local/camera_demo/bitstream_raw0b/routed.dcp}
set target_name {u_soc/i_npu_subsystem/i_npu_core/core/p_0_out__1}
set target [get_cells $target_name]
puts {AUDIT_CELL_BEGIN}
report_property $target
puts {AUDIT_CELL_END}
set modepins [get_pins -of_objects $target -filter {REF_PIN_NAME =~ OPMODE*}]
puts {AUDIT_OPMODE_BEGIN}
foreach p $modepins {
  set ns [get_nets -of_objects $p]
  puts "PIN $p NETS $ns"
  foreach n $ns {
    set ds [get_pins -of_objects $n -filter {DIRECTION == OUT}]
    puts "DRIVERS $ds"
    foreach d $ds {set c [get_cells -of_objects $d]; puts "DRIVER_CELL $c REF [get_property REF_NAME $c]"}
  }
  puts "STARTPOINTS [all_fanin -flat -startpoints_only -to $p]"
}
puts {AUDIT_OPMODE_END}
set cone [lsort -unique [all_fanin -flat -only_cells -to $modepins]]
puts "AUDIT_CONE_LENGTH [llength $cone]"
foreach c $cone {
  puts "AUDIT_CONE_CELL $c REF [get_property REF_NAME $c]"
  set init [get_property -quiet INIT $c]
  puts "INIT $init"
  foreach p [get_pins -of_objects $c] {
    set ns [get_nets -of_objects $p]
    puts "CONNECTION [get_property REF_PIN_NAME $p] $ns"
    if {[get_property DIRECTION $p] eq {IN}} {
      foreach n $ns {puts "CONNECTION_DRIVERS [get_pins -of_objects $n -filter {DIRECTION == OUT}]"}
    }
  }
}
puts {AUDIT_DONE}
close_design
exit
